// Run: node -r esm bench/index.js
// Requires: npm install inside bench/ (benchmark listed in bench/package.json)
const { Suite } = require('benchmark');
const { clsx } = require('../src/index.js');
const { clsx: lite } = require('../src/lite.js');

function bench(name, ...args) {
	console.log(`\n# ${name}`);
	new Suite()
		.add('clsx      ', () => clsx.apply(null, args))
		.add('clsx/lite ', () => lite.apply(null, args))
		.on('cycle', e => console.log('  ' + e.target))
		.on('complete', function () {
			console.log('  Fastest: ' + this.filter('fastest').map('name'));
		})
		.run();
}

bench(
	'Strings',
	'foo', '', 'bar', 'baz', 'bax', 'bux'
);

bench(
	'Objects',
	{ foo: true, bar: true, bax: true, bux: false },
	{ baz: true, bax: false, bux: true }
);

bench(
	'Arrays',
	['foo', 'bar'],
	['baz', 'bax', 'bux']
);

bench(
	'Nested Arrays',
	['foo', ['bar']],
	['baz', ['bax', ['bux']]]
);

bench(
	'Mixed',
	'foo', 'bar',
	{ bax: true, bux: false },
	['baz', { bax: false, bux: true }]
);

